#include <bits/stdc++.h>
using namespace std;

int countLess(const vector<int>& arr, int start, int val) {
    int count = 0;
    for (int i = start; i < (int)arr.size() && arr[i] < val; i++) {
        count++;
    }
    return count;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    string inputStr;
    cin >> inputStr;

    vector<int> vPositions, kPositions, xPositions;
    for (int i = 0; i < n; i++) {
        if (inputStr[i] == 'V') vPositions.push_back(i);
        else if (inputStr[i] == 'K') kPositions.push_back(i);
        else xPositions.push_back(i);
    }

    int vCount = (int)vPositions.size();
    int kCount = (int)kPositions.size();
    int xCount = (int)xPositions.size();

    const long long INF = LLONG_MAX;
    vector<vector<vector<vector<long long>>>> dp(
        vCount + 1,
        vector<vector<vector<long long>>>(
            kCount + 1,
            vector<vector<long long>>(
                xCount + 1,
                vector<long long>(2, INF)
            )
        )
    );

    dp[0][0][0][0] = 0;

    for (int vIdx = 0; vIdx <= vCount; vIdx++) {
        for (int kIdx = 0; kIdx <= kCount; kIdx++) {
            for (int xIdx = 0; xIdx <= xCount; xIdx++) {
                for (int t = 0; t < 2; t++) {
                    long long cost = dp[vIdx][kIdx][xIdx][t];
                    if (cost == INF) continue;

                    if (vIdx < vCount) {
                        int posV = vPositions[vIdx];
                        int moves = countLess(vPositions, vIdx, posV) +
                                    countLess(kPositions, kIdx, posV) +
                                    countLess(xPositions, xIdx, posV);
                        if (dp[vIdx + 1][kIdx][xIdx][1] > cost + moves) {
                            dp[vIdx + 1][kIdx][xIdx][1] = cost + moves;
                        }
                    }
                    if (kIdx < kCount && t == 0) {
                        int posK = kPositions[kIdx];
                        int moves = countLess(vPositions, vIdx, posK) +
                                    countLess(kPositions, kIdx, posK) +
                                    countLess(xPositions, xIdx, posK);
                        if (dp[vIdx][kIdx + 1][xIdx][0] > cost + moves) {
                            dp[vIdx][kIdx + 1][xIdx][0] = cost + moves;
                        }
                    }
                    if (xIdx < xCount) {
                        int posX = xPositions[xIdx];
                        int moves = countLess(vPositions, vIdx, posX) +
                                    countLess(kPositions, kIdx, posX) +
                                    countLess(xPositions, xIdx, posX);
                        if (dp[vIdx][kIdx][xIdx + 1][0] > cost + moves) {
                            dp[vIdx][kIdx][xIdx + 1][0] = cost + moves;
                        }
                    }
                }
            }
        }
    }

    long long minCost = INF;
    for (int i = 0; i < 2; i++) {
        if (dp[vCount][kCount][xCount][i] < minCost) {
            minCost = dp[vCount][kCount][xCount][i];
        }
    }
    cout << minCost << "\n";

    return 0;
}
